import * as T from './three.module.min.js';
import {STATIONS,OBSTACLES} from './navigation.mjs';
import {createOcean} from './ocean.mjs';
const C={navy:0x10283d,orange:0xff642e,cream:0xf0e6cc,sand:0xe2c28d,rock:0x697c7c,wood:0xa57048,green:0x21876c,leaf:0x53b489,white:0xf4f4e9,purple:0xb7a1f1,pink:0xf18bb3};
let seed=827;function random(){seed=(seed*16807)%2147483647;return(seed-1)/2147483646;}
const mats=new Map();function mat(color,extra={}){if(Object.keys(extra).length)return new T.MeshStandardMaterial({color,roughness:.85,...extra});if(!mats.has(color))mats.set(color,new T.MeshStandardMaterial({color,roughness:.85,flatShading:true}));return mats.get(color);}
function mesh(g,m,parent,x=0,y=0,z=0){const v=new T.Mesh(g,m);v.position.set(x,y,z);v.castShadow=true;v.receiveShadow=true;parent.add(v);return v;}
function box(p,w,h,d,c,x=0,y=0,z=0){return mesh(new T.BoxGeometry(w,h,d),mat(c),p,x,y,z);}
function cylinder(p,rt,rb,h,c,x=0,y=0,z=0,n=12){return mesh(new T.CylinderGeometry(rt,rb,h,n),mat(c),p,x,y,z);}
function sphere(p,r,c,x=0,y=0,z=0){return mesh(new T.IcosahedronGeometry(r,1),mat(c),p,x,y,z);}
function lineBetween(p,a,b,r,c){const av=new T.Vector3(...a),bv=new T.Vector3(...b),d=bv.clone().sub(av),o=cylinder(p,r,r,d.length(),c);o.position.copy(av.add(bv).multiplyScalar(.5));o.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),d.normalize());return o;}
function labelTexture(text,bg='#10283d',fg='#f2eddc',width=512,height=128){const c=document.createElement('canvas');c.width=width;c.height=height;const x=c.getContext('2d');x.fillStyle=bg;x.fillRect(0,0,width,height);x.fillStyle=fg;x.font=`900 ${height*.63}px Arial`;x.textAlign='center';x.textBaseline='middle';x.fillText(text,width/2,height*.54,width*.88);const tx=new T.CanvasTexture(c);tx.colorSpace=T.SRGBColorSpace;return tx;}
function sign(p,text,w,h,x,y,z,background='#10283d',fg='#f2eddc'){const t=labelTexture(text,background,fg);return mesh(new T.PlaneGeometry(w,h),new T.MeshBasicMaterial({map:t,side:T.DoubleSide}),p,x,y,z);}

export function createWorld(scene){
 const floats=[],flags=[],people=[],beams=[],seaDecor=[],colliders=OBSTACLES;
 const {water,uniforms:waterUniforms}=createOcean(scene);
 const foamMaterial=new T.MeshBasicMaterial({color:0x94dce0,transparent:true,opacity:.17,depthWrite:false});const foam=new T.InstancedMesh(new T.PlaneGeometry(1.6,.07),foamMaterial,350);const dummy=new T.Object3D();for(let i=0;i<350;i++){dummy.position.set((random()-.5)*190,.01,(random()-.5)*190);dummy.rotation.x=-Math.PI/2;dummy.rotation.z=-.22;dummy.scale.set(.3+random()*1.4,1,1);dummy.updateMatrix();foam.setMatrixAt(i,dummy.matrix);}scene.add(foam);
 function island(x,z,r,kind='normal'){
  const g=new T.Group();g.position.set(x,0,z);scene.add(g);
  // The sea shader handles the shallows; no hard translucent discs around islands.
  const sandGeo=new T.CylinderGeometry(r*.91,r,1.9,18);const pos=sandGeo.attributes.position;for(let i=0;i<pos.count;i++){const xx=pos.getX(i),zz=pos.getZ(i),ang=Math.atan2(zz,xx),f=1+Math.sin(ang*5+.5)*.08+Math.cos(ang*3)*.09;pos.setXYZ(i,xx*f,pos.getY(i),zz*f);}sandGeo.computeVertexNormals();mesh(sandGeo,mat(C.sand),g,0,.4,0);
  if(kind!=='beach')cylinder(g,r*.72,r*.81,1.1,0x679381,0,1.3,-.3,15);
  for(let i=0;i<5;i++){const a=random()*Math.PI*2,b=r*(.78+random()*.2);const ro=sphere(g,.6+random(),C.rock,Math.sin(a)*b,.5,Math.cos(a)*b);ro.scale.set(1.4,.85,1);}
  return g;
 }
 function palm(p,x,z,s=1,angle=0){const g=new T.Group();g.position.set(x,1.5,z);g.scale.setScalar(s);g.rotation.y=angle;p.add(g);const height=5.4;lineBetween(g,[0,0,0],[.3,2.8,0],.18,C.wood);lineBetween(g,[.3,2.8,0],[1,height,0],.14,C.wood);for(let i=0;i<6;i++){const a=i*Math.PI/3,points=[];const vertices=[];for(let j=0;j<5;j++){const t=j/4,len=t*3.3,wide=Math.sin(t*Math.PI)*.48,yy=height+Math.sin(t*Math.PI)*1.2-t*.7;points.push([[1+Math.cos(a)*len+Math.sin(a)*wide,yy,Math.sin(a)*len-Math.cos(a)*wide],[1+Math.cos(a)*len-Math.sin(a)*wide,yy,Math.sin(a)*len+Math.cos(a)*wide]]);}for(let j=0;j<4;j++){vertices.push(...points[j][0],...points[j][1],...points[j+1][0],...points[j][1],...points[j+1][1],...points[j+1][0]);}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(vertices,3));geo.computeVertexNormals();mesh(geo,mat(i%2?C.leaf:C.green,{side:T.DoubleSide}),g);}}
 function flag(p,x,y,z,color,scale=1,logo=false){const g=new T.Group();g.position.set(x,y,z);p.add(g);cylinder(g,.045,.07,4*scale,C.cream,0,2*scale,0,6);const geo=new T.PlaneGeometry(1.55*scale,.95*scale,7,2);geo.translate(.78*scale,0,0);const material=mat(color,{side:T.DoubleSide});const f=mesh(geo,material,g,0,3.4*scale,0);flags.push(f);if(logo){const l=sign(g,'BOIA',1.15*scale,.4*scale,.8*scale,3.4*scale,.035,'#ff642e','#10283d');l.rotation.y=0;}return g;}
 function dock(p,x,z,length=8,width=2.6,rot=0){const g=new T.Group();g.position.set(x,1,z);g.rotation.y=rot;p.add(g);box(g,width,.25,length,C.wood,0,0,0);for(let i=0;i<length;i++){box(g,width+.06,.04,.05,0x745342,0,.16,-length/2+i);}for(const sx of [-1,1])for(const zz of [-length/2,length/2]){cylinder(g,.13,.16,2.6,C.wood,sx*(width/2+.1),-.1,zz,7);cylinder(g,.18,.18,.2,C.cream,sx*(width/2+.1),1.23,zz,7);}return g;}
 function boat(p,x,z,scale=1,color=C.orange){const g=new T.Group();g.position.set(x,.15,z);g.scale.setScalar(scale);p.add(g);const hullShape=new T.Shape();hullShape.moveTo(-1.2,2.65);hullShape.lineTo(1.2,2.65);hullShape.lineTo(1.45,-1.3);hullShape.lineTo(.7,-2.7);hullShape.lineTo(0,-3.4);hullShape.lineTo(-.7,-2.7);hullShape.lineTo(-1.45,-1.3);hullShape.closePath();const hg=new T.ExtrudeGeometry(hullShape,{depth:.8,bevelEnabled:true,bevelSize:.16,bevelThickness:.15,bevelSegments:1,steps:1});hg.rotateX(-Math.PI/2);mesh(hg,mat(color),g,0,.05,0);const deck=mesh(hg,mat(C.cream),g,0,.85,0);deck.scale.set(.85,.12,.90);box(g,1.6,1.2,1.8,C.white,0,1.65,-.7);box(g,1.65,.55,.04,C.navy,0,1.83,.22);box(g,.04,.55,1.35,C.navy,.82,1.83,-.62);box(g,.04,.55,1.35,C.navy,-.82,1.83,-.62);box(g,1.92,.14,2.1,color,0,2.31,-.7);box(g,1.9,.3,.6,C.navy,0,1.15,-2.1);for(let i=-1;i<=1;i+=2){lineBetween(g,[i,1.2,.5],[i,1.2,1.8],.035,C.white);lineBetween(g,[i,1.2,1.8],[0,1.2,2.8],.035,C.white);}flag(g,.55,2.35,-1.1,C.orange,.45,true);const label=sign(g,'BOIA',1.1,.3,0,2.405,-.5,'#ff642e','#10283d');label.rotation.x=-Math.PI/2;return g;}
 // Lighthouse island / manifesto.
 const home=island(-39,1,10);palm(home,-4,2,.9,-.7);palm(home,3,-3,1.1,1);palm(home,-5,-4,.8,2);
 cylinder(home,1.45,2.1,8.7,C.white,1,6,0,14);cylinder(home,1.67,1.8,1.35,C.orange,1,6.5,0,14);cylinder(home,1.49,1.57,1.1,C.orange,1,9,0,14);cylinder(home,2.15,2.15,.35,C.navy,1,10.65,0,14);cylinder(home,1.3,1.3,1.7,0x9ce0db,1,11.6,0,8);cylinder(home,0,2.0,1.3,C.orange,1,13.1,0,8);for(let i=0;i<8;i++){const a=i*Math.PI/4;box(home,.1,1.8,.1,C.navy,1+Math.sin(a)*1.32,11.6,Math.cos(a)*1.32);}box(home,.9,1.8,.08,C.navy,1,2.5,1.8);const dockHome=dock(home,9.2,3,6,2.7,Math.PI/2);sign(home,'BOIA',4.2,1.3,-2.5,3,5.9,'#ff642e');flag(home,-.5,1.8,5.7,C.orange,1.15);
 const light=new T.PointLight(0xffc371,30,24,2);light.position.set(-38,11.6,1);scene.add(light);
 // Party catamaran / artists.
 const party=new T.Group();party.position.set(37,.35,-19);party.rotation.y=-.13;scene.add(party);floats.push({g:party,base:.35,phase:3,amp:.13});
 for(const x of [-4,4]){const pontoon=cylinder(party,1.2,1.2,17,C.purple,x,.05,0,10);pontoon.rotation.x=Math.PI/2;sphere(party,1.19,C.purple,x,.05,8.5);sphere(party,1.19,C.purple,x,.05,-8.5);}
 box(party,11,.6,20,C.white,0,1.0,0);box(party,10.5,.1,19.5,C.wood,0,1.35,0);box(party,9,.6,5,C.navy,0,1.7,-6.4);box(party,4,1.2,1.4,C.navy,0,2.5,-7);sign(party,'BOIA FM',5.5,1.4,0,5.4,-8,'#10283d','#ddc9ff');
 for(const x of [-4.5,4.5]){box(party,.18,6,.18,C.navy,x,4.6,-8);box(party,1.5,2.2,1.4,C.navy,x*.78,3,-6.8);for(const yy of [2.5,3.4]){const sp=cylinder(party,.43,.43,.08,0x385464,x*.78,yy,-6.05,16);sp.rotation.x=Math.PI/2;}}
 lineBetween(party,[-4.5,7.5,-8],[4.5,7.5,-8],.1,C.navy);for(let i=0;i<7;i++){const led=sphere(party,.16,[0xffbb55,0xb6acff,0x8edca1][i%3],-4+i*1.33,7.3,-7.9);led.material=mat([0xffbb55,0xb6acff,0x8edca1][i%3],{emissive:[0xffbb55,0xb6acff,0x8edca1][i%3],emissiveIntensity:1});}
 for(let i=0;i<18;i++){const g=new T.Group();const xx=(i%5-2)*1.6,zz=Math.floor(i/5)*2.1-2.8;g.position.set(xx,1.5,zz);party.add(g);cylinder(g,.22,.29,.8,[C.orange,0xc5aff2,C.white,0x63c7ab][i%4],0,.68,0,7);sphere(g,.23,0xd6a789,0,1.35,0);lineBetween(g,[-.14,.3,0],[-.18,0,0],.09,C.navy);lineBetween(g,[.14,.3,0],[.18,0,0],.09,C.navy);lineBetween(g,[-.25,.9,0],[-.4,1.2,0],.07,0xd6a789);lineBetween(g,[.25,.9,0],[.4,1.38,0],.07,0xd6a789);people.push({g,phase:random()*6});}
 for(const x of [-5,5]){lineBetween(party,[x,2.3,-8],[x,2.3,8],.055,C.white);for(let zz=-8;zz<=8;zz+=4)lineBetween(party,[x,1.4,zz],[x,2.3,zz],.055,C.white);flag(party,x,1.5,8,C.purple,.9);}
 for(const x of [-3.5,3.5]){const bm=mesh(new T.ConeGeometry(2.8,12,12,1,true),new T.MeshBasicMaterial({color:x<0?0xc1a1ff:0x88e5fa,transparent:true,opacity:.055,depthWrite:false,side:T.DoubleSide}),party,x,6,-4);bm.rotation.z=x<0?-.6:.6;beams.push(bm);}
 // Ticket harbour.
 const port=island(42,37,8.5);dock(port,-8,-5,8,3,Math.PI/2);box(port,5.7,3.7,4.7,C.orange,0,3.2,0);const roof=cylinder(port,0,4.4,2.4,C.navy,0,6.1,0,4);roof.rotation.y=Math.PI/4;box(port,3.8,1.2,.12,C.navy,0,3.65,2.4);box(port,4.5,.17,1,C.cream,0,2.96,2.8);sign(port,'TICKETS',5.2,1,0,5.02,2.5,'#ffe372','#10283d');palm(port,4,-3,.85,.8);palm(port,-3,-3,.72,-1);flag(port,-3.4,1.7,3.2,0xffe372);for(let i=0;i<3;i++){box(port,.6,.8,.6,C.cream,3.5,2,1.5+i);}
 // Food beach and long table.
 const beach=island(-12,44,10,'beach');palm(beach,-6,0,1.1,2);palm(beach,-2,-5,1,0);palm(beach,5,3,.8,1);palm(beach,6,-3,.9,3);dock(beach,5,-9,7,2.4,0);
 box(beach,6.5,.3,2,C.wood,-1,2.5,0);for(const x of [-3.5,1.5])for(const z of [-.7,.7])box(beach,.18,1.1,.18,C.navy,x,1.8,z);for(const z of [-1.7,1.7]){box(beach,6.8,.2,.6,C.orange,-1,1.85,z);for(const x of [-3.7,1.7])box(beach,.2,.6,.2,C.navy,x,1.45,z);}cylinder(beach,.85,.85,.16,C.navy,-1,2.76,0,20);cylinder(beach,.73,.73,.04,0xe8ac29,-1,2.87,0,20);for(let i=0;i<8;i++)sphere(beach,.10,[C.orange,0x50826a][i%2],-1+(random()-.5),2.92,(random()-.5));
 for(let i=0;i<3;i++){const x=-5+i*4,z=5;const umbrella=new T.Group();umbrella.position.set(x,1.5,z);beach.add(umbrella);cylinder(umbrella,.06,.07,2.8,C.cream,0,1.4,0,6);cylinder(umbrella,0,1.65,.75,[C.orange,0xffe372,0x9ba8f4][i],0,3,0,10);const ch=box(beach,1.1,.14,2.3,C.white,x,1.65,z+1.7);ch.rotation.x=-.18;}
 sign(beach,'OFF THE CLOCK',6,1,-1,3.2,-5.8,'#83d9b0','#10283d');flag(beach,3,1.4,-4,0x84e5ba,.9);
 // Art and archive cove.
 const art=island(-38,-40,9);palm(art,-4,-2,.8,1);palm(art,2,-5,.95,3);dock(art,6.6,5.8,8,2.4,Math.PI/4);const titles=['DEEP BLUE','OFF RADAR','NO LIMITS'];for(let i=0;i<3;i++){const x=-4+i*3.5;box(art,2.8,4.3,.18,[0xff6734,0x4741dd,C.navy][i],x,3.75,1);sign(art,'BOIA',2.3,.75,x,5,1.11,['#ff6734','#4741dd','#10283d'][i]);sign(art,titles[i],2.4,.65,x,3.6,1.12,['#ff6734','#4741dd','#10283d'][i]);for(const sx of [-1,1])box(art,.09,1,.09,C.wood,x+sx,1.6,1);}flag(art,-4,1.8,4,0xff9cbd);
 // Secret island and radio mast.
 const secret=island(62,-47,7);for(let i=0;i<3;i++){const ro=sphere(secret,2.2+random(),C.rock,-2+i*2.4,2.2,-1);ro.scale.y=1.4;}lineBetween(secret,[1,2,1],[1,10,1],.1,C.white);for(const y of [4,6,8]){lineBetween(secret,[-.8,y,1],[2.8,y,1],.06,C.white);}flag(secret,1,9.5,1,0x6bddfa,.65);const lamp=sphere(secret,.2,C.orange,1,10.2,1);lamp.material=mat(C.orange,{emissive:C.orange,emissiveIntensity:2});
 // Smaller islands and sailboats give the world depth.
 const tiny=island(9,-47,4);palm(tiny,0,0,.8,.5);const rock=island(-57,27,4);palm(rock,0,0,.7,2);
 for(let i=0;i<3;i++){const b=boat(scene,[-6,55,-51][i],[-22,7,-13][i],.58,[C.cream,0x65bda9,C.pink][i]);b.rotation.y=[.8,-.6,1.4][i];floats.push({g:b,base:.15,phase:i*2,amp:.13});lineBetween(b,[0,2.4,0],[0,7.3,0],.065,C.navy);const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute([.12,7,0,.12,3,0,2.6,3.2,0],3));geo.computeVertexNormals();mesh(geo,mat(C.cream,{side:T.DoubleSide}),b);}
 // Each floating buoy is a real spatial destination, separate from its landmark.
 const buoyGroups=[];for(const s of STATIONS){const g=new T.Group();g.position.set(s.x,.12,s.z);scene.add(g);const col=new T.Color(s.color);cylinder(g,1.35,1.55,.6,C.navy,0,.12,0,14);sphere(g,1.15,col,0,.78,0);cylinder(g,.28,.7,.85,C.white,0,1.7,0,10);flag(g,0,1.9,0,col,.85);const ring=mesh(new T.RingGeometry(3,3.12,48),new T.MeshBasicMaterial({color:col,transparent:true,opacity:.6,side:T.DoubleSide,depthWrite:false}),scene,s.x,.035,s.z);ring.rotation.x=-Math.PI/2;ring.castShadow=false;ring.receiveShadow=false;buoyGroups.push({g,ring,s});floats.push({g,base:.12,phase:random()*6,amp:.1});}
 const player=boat(scene,-3,8,1.05,C.orange);player.rotation.y=-.4;
 // Batch fixed geometry per material to keep mobile draw calls under control.
 function batchFixed(root,excluded){root.updateWorldMatrix(true,true);const inverse=root.matrixWorld.clone().invert(),batches=new Map(),remove=[];root.traverse(o=>{if(!o.isMesh||o.isInstancedMesh)return;for(let p=o;p&&p!==root;p=p.parent)if(excluded.has(p))return;if(o.material.map||Array.isArray(o.material))return;const geo=o.geometry.index?o.geometry.toNonIndexed():o.geometry.clone();geo.applyMatrix4(inverse.clone().multiply(o.matrixWorld));const key=o.material.uuid+o.castShadow+o.receiveShadow;let b=batches.get(key);if(!b){b={pos:[],norm:[],material:o.material,cast:o.castShadow,receive:o.receiveShadow};batches.set(key,b);}const p=geo.getAttribute('position'),n=geo.getAttribute('normal');for(let i=0;i<p.array.length;i++)b.pos.push(p.array[i]);for(let i=0;i<n.array.length;i++)b.norm.push(n.array[i]);geo.dispose();remove.push(o);});for(const o of remove)o.removeFromParent();for(const b of batches.values()){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(b.pos,3));geo.setAttribute('normal',new T.Float32BufferAttribute(b.norm,3));const m=new T.Mesh(geo,b.material);m.castShadow=b.cast;m.receiveShadow=b.receive;root.add(m);}}
 const exclude=new Set([...flags,...people.map(p=>p.g),...beams]);for(const g of [home,port,beach,art,secret,tiny,rock,party,player,...buoyGroups.map(b=>b.g),...floats.map(f=>f.g)]){if(g.userData.batched)continue;batchFixed(g,exclude);g.userData.batched=true;}
 // Reusable foam wake particles; no new geometry in the render loop.
 const wakeMaterial=new T.MeshBasicMaterial({color:0xdaefe6,transparent:true,opacity:.5,depthWrite:false});const wake=new T.InstancedMesh(new T.CircleGeometry(.17,5),wakeMaterial,100);wake.instanceMatrix.setUsage(T.DynamicDrawUsage);scene.add(wake);const wakes=Array.from({length:100},()=>({x:0,z:0,life:0,scale:1}));
 for(let i=0;i<6;i++){const bird=new T.Group();const a=box(bird,.8,.055,.13,C.cream,-.35,0,0);a.rotation.z=.25;const b=box(bird,.8,.055,.13,C.cream,.35,0,0);b.rotation.z=-.25;scene.add(bird);seaDecor.push({bird,phase:random()*6,r:15+random()*30});}
 const destinationRing=mesh(new T.RingGeometry(.75,1,32),new T.MeshBasicMaterial({color:C.orange,transparent:true,opacity:.85,side:T.DoubleSide,depthWrite:false}),scene,0,.055,0);destinationRing.rotation.x=-Math.PI/2;destinationRing.visible=false;
 return{player,water,waterUniforms,buoyGroups,colliders,destinationRing,
  update(time,dt,state,motion=true){waterUniforms.time.value=motion?time:0;const tt=motion?time:0;for(const f of floats){f.g.position.y=f.base+Math.sin(tt*1.3+f.phase)*f.amp;f.g.rotation.z=Math.sin(tt*.9+f.phase)*.022;}for(const f of flags){const p=f.geometry.attributes.position;for(let i=0;i<p.count;i++){const xx=p.getX(i);p.setZ(i,Math.sin(xx*3-tt*3.5)*.16*xx);}p.needsUpdate=true;}
   for(const p of people){p.g.position.y=1.5+Math.max(0,Math.sin(tt*5+p.phase))*.19;p.g.rotation.z=Math.sin(tt*3+p.phase)*.08;}for(let i=0;i<beams.length;i++)beams[i].rotation.z=Math.sin(tt*.65+i*2)*.4;for(const s of buoyGroups){const size=1+Math.sin(tt*1.3)*.04;s.ring.scale.setScalar(size);}
   player.position.set(state.x,.15+Math.sin(tt*1.5)*.11,state.z);player.rotation.y=state.heading;player.rotation.x=Math.sin(tt*2)*.015-Math.abs(state.speed)*.003;player.rotation.z=Math.sin(tt*1.6)*.02;
   const velocity=Math.abs(state.speed);let fresh=velocity>1&&motion?Math.ceil(velocity*dt*5):0;for(let i=0;i<wakes.length;i++){const w=wakes[i];w.life=Math.max(0,w.life-dt);if(w.life===0&&fresh>0){w.life=.9+random();const side=(random()-.5)*1.9;w.x=state.x-Math.sin(state.heading)*3.2+Math.cos(state.heading)*side;w.z=state.z-Math.cos(state.heading)*3.2-Math.sin(state.heading)*side;fresh--;}dummy.position.set(w.x,.04,w.z);dummy.rotation.set(-Math.PI/2,0,0);dummy.scale.setScalar(w.life>0?Math.max(.01,(2-w.life)*1.6):0);dummy.updateMatrix();wake.setMatrixAt(i,dummy.matrix);}wake.instanceMatrix.needsUpdate=true;
   for(const o of seaDecor){o.bird.position.set(Math.cos(tt*.08+o.phase)*o.r,13+Math.sin(tt+o.phase)*.35,Math.sin(tt*.08+o.phase)*o.r);o.bird.rotation.y=-(tt*.08+o.phase);}
  }};
}
